using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SingularityGoddessEffect", menuName = "Data/Battle/Effects/Enemy/SingularityGoddess Effect")]
public class SingularityGoddessEffect : Effect
{
	[Header("State Changer")]
	[SerializeField]
	private CorruptedAnimalData stateOneAstreaCorruptedAnimalData;

	[SerializeField]
	private CorruptedAnimalData stateTwoAstreaCorruptedAnimalData;

	[Header("Hex Action")]
	[SerializeField]
	private HexAction woundHexAction;

	[SerializeField]
	private HexAction dizzyHexAction;

	[SerializeField]
	private HexAction confuseHexAction;

	[SerializeField]
	private HexAction paralyzedHexAction;

	[SerializeField]
	private HexAction madnessHexAction;

	[SerializeField]
	private HexAction plagueHexAction;

	[Header("Decay Effect")]
	[SerializeField]
	private int turnsToGainDecay;

	[SerializeField]
	private DecayEffect decayEffect;

	[Header("Astrea Level")]
	[SerializeField]
	private DifficultyLevel astreaLevel;

	[NonSerialized]
	private int startingAmount;

	[NonSerialized]
	private bool stateOne;

	[NonSerialized]
	private bool changingAstreaState;

	public bool StateOne => stateOne;

	public bool ChangingAstreaState => changingAstreaState;

	public void SetStateOneCorruptedAnimalData(CorruptedAnimalData stateOneAstreaCorruptedAnimalData)
	{
		this.stateOneAstreaCorruptedAnimalData = stateOneAstreaCorruptedAnimalData;
	}

	public void SetStateTwoCorruptedAnimalData(CorruptedAnimalData stateTwoAstreaCorruptedAnimalData)
	{
		this.stateTwoAstreaCorruptedAnimalData = stateTwoAstreaCorruptedAnimalData;
	}

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedAtTheStartOfTheBattle(), Smart.Format(base.localizationManager.GetLocalizedEveryXTurns(), turnsToGainDecay), 1, decayEffect.GetEffectName(), startingAmount, amount);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		startingAmount = effectAmount;
		stateOne = true;
		changingAstreaState = false;
		woundHexAction.CastAmount(1, effectOwner);
		dizzyHexAction.CastAmount(1, effectOwner);
		confuseHexAction.CastAmount(1, effectOwner);
		paralyzedHexAction.CastAmount(1, effectOwner);
		madnessHexAction.CastAmount(1, effectOwner);
		plagueHexAction.CastAmount(1, effectOwner);
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter % turnsToGainDecay == 0)
		{
			UnitEffects component = effectOwner.GetComponent<UnitEffects>();
			component.IsEffectActive(this);
			component.AddEffect(decayEffect, 1);
		}
		return effectAmount;
	}

	public override int ActivateEffectWithSource(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (changingAstreaState)
		{
			return effectAmount;
		}
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		int num = effectAmount - 1;
		if (num == 0)
		{
			changingAstreaState = true;
			instance.ActionsQueueState.EnqueueAfterAction(ChangeAstreaStateAfterActivatingHerDice(effectOwner, component));
			instance.SetActionsQueueState();
		}
		component.IsEffectActiveAndDecreaseEffect(this, 1, activateFeedback: true, removeOnZero: false);
		if (num == 1)
		{
			component.IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
		}
		return effectAmount;
	}

	private IEnumerator ChangeAstreaStateAfterActivatingHerDice(GameObject effectOwner, UnitEffects unitEffects)
	{
		yield return InvokeAlternatives.WaitForFrames(3);
		if (!effectOwner.activeInHierarchy)
		{
			yield break;
		}
		SpawnVFX(GetVFXOwnerPosition(effectOwner), 5f);
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
		}
		CorruptedAnimalActivation component = effectOwner.GetComponent<CorruptedAnimalActivation>();
		CorruptedAnimalInitializer component2 = effectOwner.GetComponent<CorruptedAnimalInitializer>();
		SpriteControl spriteControl = effectOwner.GetComponent<SpriteControl>();
		int difficultyLevelModifyEnemiesHighestIndex = astreaLevel.GetDifficultyLevelModifyEnemiesHighestIndex();
		StartingEffect startingEffect = stateOneAstreaCorruptedAnimalData.StartingEffectsList[difficultyLevelModifyEnemiesHighestIndex].startingEffects[1];
		Dice dice = stateOneAstreaCorruptedAnimalData.DiceList[difficultyLevelModifyEnemiesHighestIndex];
		StartingEffect startingEffect2 = stateTwoAstreaCorruptedAnimalData.StartingEffectsList[difficultyLevelModifyEnemiesHighestIndex].startingEffects[1];
		Dice dice2 = stateTwoAstreaCorruptedAnimalData.DiceList[difficultyLevelModifyEnemiesHighestIndex];
		Dice defaultDice;
		if (stateOne)
		{
			unitEffects.RemoveEffect(startingEffect.Effect);
			unitEffects.AddEffect(startingEffect2.Effect, startingEffect2.EffectAmount);
			defaultDice = dice2;
			component2.CorruptedAnimalOverCorruption.Initialize(stateTwoAstreaCorruptedAnimalData);
			spriteControl.PlayAnimationForced(AnimationType.Skill1, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
			{
				spriteControl.PlayAnimationForced(AnimationType.Idle1, AnimationChangeType.StayInTheNewAnimationLooping);
			});
		}
		else
		{
			unitEffects.RemoveEffect(startingEffect2.Effect);
			unitEffects.AddEffect(startingEffect.Effect, startingEffect.EffectAmount);
			defaultDice = dice;
			component2.CorruptedAnimalOverCorruption.Initialize(stateOneAstreaCorruptedAnimalData);
			spriteControl.PlayAnimationForced(AnimationType.Skill, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
			{
				spriteControl.PlayAnimationForced(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
			});
		}
		List<DiceInstance> diceInstancesToRoll = component.GetDiceInstancesToRoll();
		component.InitializeWithoutStoreDiceWithoutResettingEmpowerAndHideDiceface(defaultDice);
		component.UpdateActionValueModifier();
		component.UpdateDiceInstances();
		diceInstancesToRoll.RemoveAll((DiceInstance item) => item.DiceState == DiceState.Rolling);
		if (diceInstancesToRoll.Count > 0)
		{
			ReferenceSingleton<AssetsReference>.Instance.RerollAction.ExternalCast(diceInstancesToRoll, RollDiceActionType.REARM, null);
		}
		stateOne = !stateOne;
		yield return InvokeAlternatives.WaitForFrames(3);
		unitEffects.RemoveEffect(this, activateFeedback: false);
		changingAstreaState = false;
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().AddEffect(this, startingAmount, effectFeedback: true, callEffectsCallbacks: false);
	}
}
